// th15_s7_b7 — TH15 v1.00b Extra Stage Boss4 (nonspell, rank 4).
// Source entry: st07bs.ecl.txt:483-568. Dependencies: Boss4_at 570-600,
// Boss4_pos 643-652, BossB4 st07bs2.ecl.txt:84-106.
// Card frame 0 is the shell start; the source entry is spawned after OPENING_BUFFER.
const TIME_LIMIT: int = 3724;   // 120 buffer + 3600 source interrupt + 4 startup margin
const OPENING_BUFFER: int = 120;

// TH15 source type 4 -> existing modern catalog slot TH15_BALL (radius 4, colors 0-15).
const TH15_BALL: int = 416;
const BALL_COLOR: int = 6;
const RING_WAYS: int = 90;

// Shell: control owns the phase; Boss and the second body are separate real enemies.
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // st07.ecl.txt:968-969 creates Boss and BossB before the fight. The card enters at
    // Boss4, so both bodies are seeded at their Boss()/BossB() entry position (0,128).
    // BossB is the cross-enemy target of enmCall($GI0,"BossB4") at st07bs.ecl.txt:496.
    _ = spawn_enemy(0fx, 128fx, 19000, 0, 0, 0, boss4_main);
    _ = spawn_enemy(0fx, 128fx, 17001, 0, 0, 0, bossb4_body);
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// ---------------------------------------------------------------------------
// Cross-enemy BossB4 (st07bs2.ecl.txt:84-106). It carries no bullets in this
// card; only its body/life/motion matter. enmCall() is represented by spawning
// the body with this program at the same source frame.
async sub bossb4_body() {
    // Context BossB() st07bs2.ecl.txt:6-37: hurtbox 40x40, hitbox 48x48.
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);

    // 86: movePos(192,-64). 92-97: timerReset, invuln, flags, moveLimitReset.
    move_to(0, 192fx, -64fx, EASE_LINEAR);
    // 96-98: movePosTime(180,1,0,128); wait(185).
    move_to(180, 0fx, 128fx, EASE_QUAD_IN);
    wait(185);
    // 99: flagSet(35) sets the source body-block bit 0x2 (TH16 mapping); the
    // other bits are damage/ANM state and are covered by the shell.
    set_enemy_flag(ENEMY_NO_BODY, 1);
    loop { wait(1000); }
}

// ---------------------------------------------------------------------------
// st07bs.ecl.txt:483-568 Boss4 body.
async sub boss4_main() {
    // Context Boss() st07bs.ecl.txt:8-39: hurtbox 40x40, hitbox 48x48, pos (0,128).
    // The shell keeps permanent invulnerability; source setInvuln(190) is superseded.
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);

    // 489-551: etCancel(640), bombShield, fog, BossItemPhase3, timerReset,
    // killAllAsync, enmKillAll, spellEnd, funcSet(0), laserCancel, sound,
    // anm/stars, moveLimitReset. The isolated card starts with an empty field and
    // no player DPS, so the clearing/reward/presentation calls are no-ops here.
    // 515-517: stop inherited motion.
    move_vel(0, 0deg, 0fx, EASE_LINEAR);

    // 524-528: moveLimitReset(); movePosTime(60,4,-80,128); wait(60).
    move_to(60, -80fx, 128fx, EASE_QUAD_OUT);
    wait(60);
    // 527-528: movePosTime(120,1,-192,-80); wait(120).
    move_to(120, -192fx, -80fx, EASE_QUAD_IN);
    wait(120);
    // 536: movePos(0,128).
    move_to(0, 0fx, 128fx, EASE_LINEAR);

    // 543-552: wait(30), wait(50), async Boss4_pos(), wait(60).
    // Boss4_pos() is an every-frame enm322(3,0) call. Public docs list 322 as
    // unknown; it is omitted (see report.md) and consumes no et/bullet state.
    wait(30);
    wait(50);
    wait(60);

    // 553-555: %F0 = 0.017453f; $I0 = 5. %F0 is read only by omitted Boss4_pos.
    var shots: int = 5;
    loop {
        boss4_at(shots);                       // 557: @Boss4_at($I0, 90)
        if shots < 10 { shots = shots + 1; }   // 558-559
        wait(120);                             // 562
        move_rand_1_9();                       // 563: moveRand(60,4,1.9)
        card_wait(60);                         // 564: wait(60) covers the 60 move ticks
    }
}

// Boss4_at: 90-way fixed ring, speed 2.0, one layer, type 4 / color 6.
// EX ANIM a=1 birth displacement is -4*velocity = -8px along each bullet angle.
sub boss4_at(shots: int) {
    // 573-580: etNew(0); etAim(0,3); etSprite(0,4,6); etCount(0,90,1);
    // etAngle(0,0,0); etSpeed(0,2.0,0.2); EX ANIM(1) and BRIGHT(1).
    sh_reset(0);
    sh_sprite(0, TH15_BALL, BALL_COLOR);
    sh_ring(0, 1);              // etAim mode 3: fixed-direction ring
    sh_aim(0, 0);
    sh_count(0, RING_WAYS, 1);
    sh_speed(0, 2fx, 0fx);
    sh_dist(0, -8fx);           // ANIM a=1: position -= 4*velocity

    // 581: %D = %RANDRAD is the first shot's base angle.
    var dir: angle = rand(65536) as angle;
    var half: int = 32768 / RING_WAYS;  // (%E/2), E=2pi/90, in BAM
    var c: int = 0;
    while c < shots {
        sh_angle(0, dir, 0deg);  // 588 stores the current %D in the emitter
        // 589-593: after shots 0..2 %D is replaced by a new random; from
        // shot 3 on it advances by %E/2 for the next shot.
        if c < 3 {
            dir = rand(65536) as angle;
        } else {
            dir = dir + (half as angle);
        }
        sh_fire(0);              // 595 etOn uses the angle stored above
        wait(10);                // 596
        c = c + 1;
    }
}

// ---------------------------------------------------------------------------
// Source 412 moveRand(60,4,1.9) at st07bs.ecl.txt:563. Fixed direction is
// sampled once; speed is 1.9*(60-k)/60 for the k=1..60 movement ticks.
// moveLimit(0,128,280,64) gives actual x[-140,140], y[96,160]; the direction
// branches use the inner +/-70 and 112..144 bounds.
sub mr_begin() {
    var r: int = rand(65536) - 32768;  // signed unit * pi, in BAM
    var a: int = 0;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // +/-pi/2 guard, epsilon 0.05rad in BAM.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    mr_arm_next();
}

// Prepare the next source movement tick; phase 5 then performs it.
sub mr_arm_next() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60 * 1.9fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub move_rand_1_9() {
    mr_begin();
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        mr_arm_next();
    }
}
